/** 진짜 Paper/PG의 제어 세션/저장 경계입니다. Player·인증·클라이언트 행동을 합성하지 않습니다. */
public final class NetworkBackendVerification {
    private static final UUID PLAYER=new UUID(0x4e4554,1),RAW=new UUID(0x4e4554,2);
    private NetworkBackendVerification(){}
    private static void check(JavaPlugin p,boolean value,String name){if(!value)throw new IllegalStateException("NETWORK_CHECK_FAILED_"+name);p.getLogger().info("HEARTH_NETWORK_CHECK PASS "+name);}
    private static <T> CompletionStage<T> on(CompletionStage<T> task,Executor owner){return task.thenApplyAsync(v->v,owner);}
    private static CompletionStage<Void> waitFor(JavaPlugin p,BooleanSupplier condition,int ticks){if(condition.getAsBoolean())return CompletableFuture.completedFuture(null);if(ticks>160)return CompletableFuture.failedFuture(new IllegalStateException("NETWORK_PROBE_TIMEOUT"));var f=new CompletableFuture<Void>();Bukkit.getScheduler().runTaskLater(p,()->waitFor(p,condition,ticks+1).whenComplete((v,e)->{if(e==null)f.complete(null);else f.completeExceptionally(e);}),1);return f;}
    private static final class InventoryPort implements PlayerSessions.Port {InventoryPayload value;public boolean connected(){return true;}public InventoryPayload capture(){return value;}public void apply(InventoryPayload payload){value=payload;}public CompletionStage<Boolean> move(){return CompletableFuture.completedFuture(true);}}
    public static CompletionStage<Void> run(JavaPlugin p,EconomyRuntime runtime,PostgresProgressStore db){
        final Path root;try{root=IsolatedPaths.require(Path.of(System.getProperty("hearth.network.verification.root","")),"hearth-network-run.");if(!Files.readString(root.resolve(".hearth-network-isolated")).equals("Hearth network isolated v1\n")||!Path.of("").toRealPath().equals(root.resolve("economy"))||!Bukkit.getOnlinePlayers().isEmpty()||p.getConfig().getBoolean("verification-enabled"))throw new IllegalStateException("NETWORK_PROBE_GATE");Files.createFile(root.resolve("network-probe.started"));}catch(Exception e){return CompletableFuture.failedFuture(e);}
        var settings=Objects.requireNonNull(BackendAuthentication.settings(p,"economy"));BackendAuthentication.require(settings);check(p,!Bukkit.getOnlineMode()&&runtime.phase()==EconomyRuntime.Phase.READY,"actual_loaded_modern_forwarding_authentication_with_backend_offline_mode");boolean wrong=false,direct=false;try{BackendAuthentication.require(new NetworkSettings(settings.network(),settings.server(),settings.lobby(),settings.economy(),settings.relayEnvironment(),settings.forwardingEnvironment()));}catch(IllegalStateException denied){wrong=true;}try{BackendAuthentication.require(null);}catch(IllegalStateException denied){direct=true;}check(p,wrong,"actual_loaded_modern_secret_mismatch_is_refused_without_relaxing_authentication");check(p,direct,"backend_offline_mode_cannot_fall_back_to_direct_authentication");var owner=runtime.owner();var economy=runtime.economy();var codec=new PaperInventoryCodec();var empty=codec.encode(new ItemStack[41]);var actor=economy.store.context(economy.realm,PLAYER);var raw=economy.store.context(economy.realm,RAW);var port=new InventoryPort();var session=new PlayerSessions.Session[1];var transfer=new BackendTransfer(settings,System::currentTimeMillis,owner);var sent=new ArrayList<NetworkProtocol.Frame>();var token=new Object();var frozen=new boolean[1];var expected=new InventoryPayload[1];
        return on(db.module("network_fixture_database",c->{try(var st=c.createStatement();var rows=st.executeQuery("SHOW data_directory")){if(!rows.next()||!Path.of(rows.getString(1)).toRealPath().equals(root.resolve("data")))throw new IllegalStateException("NETWORK_FIXTURE_DATABASE");}return null;}),owner).thenCompose(v->on(economy.store.ensureAccount(actor,empty),owner)).thenCompose(v->{session[0]=economy.sessions.connect(actor,economy.world,port);return on(session[0].ready(),owner);}).thenRunAsync(()->{var slots=codec.decode(port.value);slots[0]=new ItemStack(Material.STONE,32);port.value=codec.encode(slots);expected[0]=port.value;transfer.begin(PLAYER,token,new BackendTransfer.Port(){public boolean current(){return economy.sessions.playable(session[0]);}public void freeze(boolean value){frozen[0]=value;}public CompletionStage<Void> save(){return economy.sessions.saveBoundary(session[0]);}public void send(NetworkProtocol.Frame f){sent.add(f);}public void notice(String code){}});check(p,frozen[0]&&sent.isEmpty(),"source_is_frozen_before_actual_PG_save_and_no_frame_is_sent_early");},owner)
            .thenCompose(v->waitFor(p,()->sent.size()==1,0)).thenCompose(v->on(economy.store.account(actor),owner)).thenAccept(row->check(p,row.inventory().revision()==1&&codec.equivalent(row.inventory().payload(),expected[0]),"proxy_request_is_released_only_after_latest_real_inventory_commit"))
            .thenRunAsync(()->{transfer.response(PLAYER,token,NetworkProtocol.response(sent.getFirst(),NetworkProtocol.Kind.REJECTED));check(p,!frozen[0]&&transfer.phase(PLAYER).isEmpty(),"known_target_refusal_keeps_same_current_source_inventory");},owner)
            .thenCompose(v->on(economy.sessions.disconnect(session[0]),owner)).thenCompose(v->on(economy.store.account(actor),owner)).thenAccept(row->check(p,row.inventory().revision()==1&&codec.equivalent(row.inventory().payload(),expected[0]),"disconnect_does_not_reissue_or_reinitialize_saved_source_items"))
            .thenCompose(v->on(economy.store.ensureAccount(raw,empty),owner)).thenCompose(v->on(db.module("network_failure_fixture",c->{try(var st=c.createStatement()){st.execute("CREATE FUNCTION hearth_economy.reject_network_probe() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.player_uuid='"+RAW+"'::uuid THEN RAISE EXCEPTION 'isolated network failure' USING ERRCODE='23514'; END IF; RETURN NEW; END $$");st.execute("CREATE TRIGGER reject_network_probe BEFORE UPDATE ON hearth_economy.account FOR EACH ROW EXECUTE FUNCTION hearth_economy.reject_network_probe()");}return null;}),owner))
            .thenCompose(v->{var failure=new BackendTransfer(settings,System::currentTimeMillis,owner);var rawSent=new ArrayList<NetworkProtocol.Frame>();failure.begin(RAW,token,new BackendTransfer.Port(){public boolean current(){return true;}public void freeze(boolean value){}public CompletionStage<Void> save(){return economy.store.saveInventory(raw,0,expected[0]).thenApply(x->null);}public void send(NetworkProtocol.Frame f){rawSent.add(f);}public void notice(String code){}});return waitFor(p,()->failure.phase(RAW).orElse(null)==BackendTransfer.Phase.HOLD,0).thenCompose(x->on(economy.store.account(raw),owner)).thenAccept(row->check(p,rawSent.isEmpty()&&row.inventory().revision()==0&&codec.equivalent(row.inventory().payload(),empty),"real_23514_save_failure_preserves_original_payload_and_sends_no_transfer"));})
            .thenCompose(v->on(db.module("network_failure_cleanup",c->{try(var st=c.createStatement()){st.execute("DROP TRIGGER reject_network_probe ON hearth_economy.account");st.execute("DROP FUNCTION hearth_economy.reject_network_probe()");}return null;}),owner))
            .thenCompose(v->on(economy.store.saveInventory(raw,0,expected[0]).handle((r,e)->e==null?"OK":InventorySaveSession.code(e)).thenCombine(economy.store.saveInventory(raw,0,expected[0]).handle((r,e)->e==null?"OK":InventorySaveSession.code(e)),(a,b)->Set.of(a,b).equals(Set.of("OK","CAS_CONFLICT"))),owner)).thenAccept(ok->check(p,ok,"real_concurrent_source_revision_has_exactly_one_CAS_winner"))
            .thenRunAsync(transfer::close,owner);
    }
}
